Let me design the example to showcase:
- Suite registration: `var _ = check.Suite(&CalculatorSuite{})` or `check.Suite(&Suite{})`
- `check.TestingT` hook: `func Test(t *testing.T) { check.TestingT(t) }`
- Fixtures: SetUpSuite/TearDownSuite, SetUpTest/TearDownTest
- Use `c.Assert`, `c.Check`

Let me write calculator.go:

```go
package gocheckdemo

import "errors"

var ErrDivByZero = errors.New("division by zero")

type Calculator struct {
	history []string
}

func New() *Calculator {
	return &Calculator{}
}

func (c *Calculator) Add(a, b int) int {
	c.history = append(c.history, "add")
	return a + b
}

func (c *Calculator) Div(a, b int) (int, error) {
	if b == 0 {
		return 0, ErrDivByZero
	}
	c.history = append(c.history, "div")
	return a / b, nil
}

func (c *Calculator) History() []string {
	out := make([]string, len(c.history))
	copy(out, c.history)
	return out
}
```

