		"  in FixtureHelper.trace\n" +
		".*check_test.go:[0-9]+\n" +
		"  in FixtureHelper.SetUpTest\n" +
		"(.|\n)*" +
		"\n-+\n" +
		"PANIC: check_test\\.go:[0-9]+: " +
		"FixtureHelper\\.Test1\n\n" +
		"\\.\\.\\. Panic: Fixture has panicked " +
		"\\(see related PANIC\\)\n$"

	c.Check(output.value, Matches, expected)
}

